<script setup>
import { computed, ref, nextTick, onBeforeUnmount } from 'vue'
import TarotTable from '../components/TarotTable.vue'
import TestResultSave from '../components/TestResultSave.vue'
import { useTarotNarration } from '../composables/useTarotNarration'
import { spreads, createMockDeck, mockReading } from '../data/tarot-mock'
const phase=ref('prepare')
const voice=useTarotNarration()
function cardText(card){return `这张牌是${card.name}，${card.orientation}。它对应的是，${card.position}。${card.theme}。${card.observation}\n${card.guidance}\n${card.prompt}`}
function chooseReading(index){current.value=index;voice.speak(cardText(readings.value[index]))}
function listen(){voice.enabled.value=true;voice.speak(phase.value==='reading'?cardText(readings.value[current.value]):messages.value.at(-1).text)}
const spreadId=ref('three'), question=ref(''), deck=ref([]), selected=ref([]), focused=ref(-1), current=ref(0), journal=ref(''), session=ref(0), title=ref(null)
const spread=computed(()=>spreads.find(s=>s.id===spreadId.value))
const readings=computed(()=>selected.value.map((index,i)=>mockReading(deck.value[index],spread.value.positions[i])))
const full=computed(()=>selected.value.length===spread.value.positions.length)
const messages=computed(()=>{
  const opening='我是星栈的引导者。先把一个想探索的问题放在这里，我们一起用牌面梳理此刻的感受。'
  if(phase.value==='prepare')return [{role:'guide',text:opening}]
  const list=[{role:'you',text:question.value.trim()||'我想了解此刻的自己。'},{role:'guide',text:full.value?'你的牌已到齐。准备好后，进入解读。':'不必寻找正确的牌。选择让你愿意停留的一张，依次留下 '+spread.value.positions.length+' 张。'}]
  if(selected.value.length)list.push({role:'guide',text:phase.value==='reading'?readings.value[current.value].theme:'你已选下 '+selected.value.length+' 张。'+(full.value?'把这次相遇带进生活。':'下一张对应「'+spread.value.positions[selected.value.length]+'」。')})
  return list
})
const record=computed(()=>phase.value==='reading'?{type:'tarot',title:'星栈映照 · '+spread.value.name,summary:question.value.trim()||'一次牌面自我观察',sections:[{title:'牌面解读（模拟）',lines:readings.value.map(c=>c.position+' · '+c.name+'（'+c.orientation+'）：'+c.theme+'。'+c.observation+' '+c.guidance+' '+c.prompt)},{title:'带回生活',lines:['选一件可以在本周完成的小行动。解读是模拟提示，不是预测。']}] }:null)
async function start(){phase.value='select';deck.value=createMockDeck();selected.value=[];focused.value=-1;current.value=0;session.value++;await nextTick();title.value?.focus();voice.speak(`先放松一下，我们慢慢来。桌上有十二张牌，请选出${spread.value.positions.length}张。不用急，先选一张让你愿意停留的牌。`)}
function pick(index){if(phase.value!=='select'||full.value||selected.value.includes(index))return;selected.value=[...selected.value,index];voice.speak(full.value?'你的牌已经选齐了。准备好后，我们一起看看它们带来的线索。':`好，这张牌已经为你留下了。下一张，看看${spread.value.positions[selected.value.length]}。`)}
async function read(){if(!full.value)return;phase.value='reading';current.value=0;await nextTick();title.value?.focus();chooseReading(0)}
function reset(){voice.clear();phase.value='prepare';selected.value=[];deck.value=[];journal.value='';focused.value=-1}
function authChanged(){reset()}
window.addEventListener('mengsu:auth-change',authChanged)
onBeforeUnmount(()=>window.removeEventListener('mengsu:auth-change',authChanged))
</script>
<template>
  <div class="tarot-sanctum">
    <header class="sanctum-header"><div><p class="overline">心绪活动 / STELLAR TAROT</p><h1>塔罗 · 星栈映照</h1></div><span class="edition"><i></i> AI 引导 · 模拟体验</span></header>
    <nav class="ritual-steps" aria-label="占卜进度"><span :class="{active:phase==='prepare'}">01 写下问题</span><span :class="{active:phase==='select'}">02 与牌相遇</span><span :class="{active:phase==='reading'}">03 解读与回看</span></nav>
    <div class="sanctum-layout">
      <section class="ritual-main">
        <template v-if="phase==='prepare'">
          <div class="intro-emblem" aria-hidden="true"><svg viewBox="0 0 200 160"><circle cx="100" cy="76" r="51"/><circle cx="100" cy="76" r="39"/><path d="M100 13v126M37 76h126M65 41l70 70M65 111l70-70M100 32l13 31 32 13-32 13-13 31-13-31-32-13 32-13Z"/><circle cx="28" cy="76" r="3"/><circle cx="172" cy="76" r="3"/></svg></div>
          <div class="prepare-copy"><p class="overline">把目光放回自己</p><h2>今晚，想问些什么？</h2><p>让一张牌成为入口，留一点时间给自己的感受。</p></div>
          <form @submit.prevent="start" class="question-form">
            <label for="tarot-question">你的问题 <small>可选 · 300 字以内</small></label>
            <textarea id="tarot-question" v-model="question" rows="2" maxlength="300" placeholder="例如：最近让我犹豫的事，我能从哪里开始？"></textarea>
            <fieldset><legend>选择牌阵</legend><div class="spread-options"><label v-for="item in spreads" :key="item.id" :class="{chosen:spreadId===item.id}"><input v-model="spreadId" type="radio" :value="item.id" name="spread"><span><strong>{{item.name}}</strong><small>{{item.note}}</small></span></label></div></fieldset>
            <button class="gold-button" type="submit">开始选牌 <span aria-hidden="true">→</span></button>
          </form>
        </template>
        <template v-else>
          <div class="table-heading"><div><p class="overline">{{phase==='reading'?'你的本次牌阵':'选择顺序对应牌阵位置'}}</p><h2 ref="title" tabindex="-1">{{spread.name}}</h2></div><button class="quiet-button" @click="reset">重新开始</button></div>
          <TarotTable :key="session" :cards="deck" :selected="selected" :limit="spread.positions.length" :locked="phase==='reading'||full" :focused="focused" @pick="pick" />
          <div class="table-controls">
            <p role="status">{{phase==='reading'?'已翻开 '+selected.length+' 张牌':full?'选牌完成':'已选 '+selected.length+' / '+spread.positions.length+' 张'}}<span v-if="!full"> · 下一张：{{spread.positions[selected.length]}}</span></p>
            <div class="card-numbers" aria-label="用牌号选择，支持键盘和触屏"><button v-for="(card,i) in deck" :key="i" :class="{picked:selected.includes(i)}" :aria-label="'第 '+(i+1)+' 张牌'+(selected.includes(i)?'，已选择':'')" :aria-pressed="selected.includes(i)" :disabled="(full||phase==='reading')&&!selected.includes(i)" @focus="focused=i" @blur="focused=-1" @mouseenter="focused=i" @mouseleave="focused=-1" @click="pick(i)">{{String(i+1).padStart(2,'0')}}<span v-if="selected.includes(i)">·</span></button></div>
            <div class="selected-slots"><span v-for="(pos,i) in spread.positions" :key="pos" :class="{filled:readings[i]}"><small>{{pos}}</small><strong>{{readings[i]?readings[i].name:'待选择'}}</strong></span></div>
            <button v-if="phase==='select'" class="gold-button" :disabled="!full" @click="read">{{full?'进入解读':'请选满 '+spread.positions.length+' 张牌'}} <span aria-hidden="true">→</span></button>
          </div>
          <section v-if="phase==='reading'" class="reading-section">
            <div class="reading-tabs" aria-label="查看各张牌的解读"><button v-for="(card,i) in readings" :key="i" :aria-pressed="current===i" :class="{active:current===i}" @click="chooseReading(i)">{{i+1}} · {{card.position}}</button></div>
            <article class="reading-detail" aria-live="polite"><div class="reading-title"><span>{{String(current+1).padStart(2,'0')}}</span><div><small>{{readings[current].position}} / {{readings[current].orientation}}</small><h2>{{readings[current].name}}</h2></div></div><h3>{{readings[current].theme}}</h3><p>{{readings[current].observation}}</p><p class="angle-note">{{readings[current].guidance}}</p><blockquote>{{readings[current].prompt}}</blockquote></article>
            <div class="takeaway"><h3>带回生活的一小步</h3><p>选择最有共鸣的一张，写下一件真实经历，再给自己安排一个可以完成的小行动。</p></div>
            <TestResultSave :record="record" />
          </section>
        </template>
      </section>
      <aside class="guide-panel" aria-label="AI 模拟引导"><div class="guide-heading"><span class="guide-avatar" aria-hidden="true">✧</span><div><strong>星栈引导</strong><small>陪你把问题慢慢展开</small></div></div><div class="narration-controls" aria-label="人声播报控制"><div class="narration-label"><strong>星栈 · 人声引导</strong><small>{{voice.status.value==='loading'?'正在准备声音…':voice.status.value==='speaking'?'正在播报':voice.status.value==='paused'?'已暂停':voice.status.value==='error'?'播报暂不可用':voice.status.value==='blocked'?'等待播放':'Serena · 千问人声'}}</small></div><div class="narration-buttons"><button class="quiet-button" @click="listen">{{phase==='prepare'?'试听引导':'听当前解读'}}</button><button class="quiet-button" :disabled="!voice.caption.value" @click="voice.replay">重听</button><button class="quiet-button" :disabled="!['speaking','paused','loading'].includes(voice.status.value)" @click="voice.pause">{{voice.status.value==='paused'?'继续':voice.status.value==='loading'?'取消等待':'暂停'}}</button><button class="quiet-button" :aria-pressed="!voice.enabled.value" @click="voice.toggle">{{voice.enabled.value?'关闭声音':'开启声音'}}</button></div><p v-if="voice.notice.value" class="narration-notice" role="status" aria-live="polite">{{voice.notice.value}}</p></div><div class="guide-messages" aria-live="polite"><div v-for="(m,i) in messages" :key="i" class="guide-bubble" :class="m.role"><small>{{m.role==='you'?'你':'引导者'}}</small><p>{{m.text}}</p></div></div><div class="guide-footer"><span class="mini-star" aria-hidden="true">✦</span><p>牌面是随机的。哪些提示与你相符，由你来决定。</p></div></aside>
    </div>
  </div>
</template>
<style scoped>
.tarot-sanctum{--gold:#d1b984;--ink:#e5dfd1;--muted:#a6aea9;max-width:1200px;margin:12px auto 30px;background:#10181d;border:1px solid #344047;border-radius:16px;color:var(--ink);font:15px/1.7 var(--body, sans-serif);overflow:hidden;padding:28px}.sanctum-header{display:flex;align-items:center;justify-content:space-between;gap:16px}.overline{font-size:11px;letter-spacing:.08em;color:#b5a47f;margin:0 0 7px}.tarot-sanctum h1{font:500 28px/1.5 var(--display,serif);margin:0}.tarot-sanctum h2{font:500 23px/1.5 var(--display,serif);margin:0 0 8px}.tarot-sanctum h3{font-size:17px;font-weight:500;margin:0 0 10px}.edition{display:flex;align-items:center;gap:8px;font-size:11px;color:#bdb7a7;white-space:nowrap}.edition i{width:5px;height:5px;border-radius:50%;background:#d1b984}.ritual-steps{display:flex;gap:28px;border-bottom:1px solid #344047;margin:22px 0 24px;padding-bottom:14px;color:#7f8c91;font-size:12px}.ritual-steps .active{color:var(--gold)}.sanctum-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:24px}.ritual-main{min-width:0;border:1px solid #303c43;border-radius:10px;background:#141e24;overflow:hidden}.intro-emblem{height:138px;display:grid;place-items:center;background:radial-gradient(ellipse at center,#253332,#141e24 70%)}.intro-emblem svg{width:180px;height:140px;stroke:#c6b181;fill:none;stroke-width:.7}.prepare-copy{padding:0 26px}.prepare-copy>p:last-child{color:var(--muted);margin:0 0 22px;font-size:14px}.question-form{padding:0 26px 26px}.question-form>label{display:flex;justify-content:space-between;gap:8px;font-size:13px;margin-bottom:8px}.question-form small{color:#a6aea9;font-size:11px}.tarot-sanctum textarea{display:block;box-sizing:border-box;width:100%;background:#0f191f;border:1px solid #46545a;border-radius:6px;color:var(--ink);font:inherit;resize:vertical;padding:12px;min-height:92px}.tarot-sanctum textarea::placeholder{color:#88959a}.tarot-sanctum fieldset{border:0;padding:0;margin:20px 0 22px}.tarot-sanctum legend{font-size:13px;margin-bottom:10px}.spread-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.spread-options label{display:flex;align-items:center;gap:9px;background:#172229;border:1px solid #35434a;border-radius:6px;padding:11px;cursor:pointer;min-width:0}.spread-options label.chosen{border-color:#bda676;background:#24302d}.spread-options input{appearance:auto!important;width:13px!important;height:13px!important;min-width:13px;accent-color:#cbb17f;margin:0;padding:0}.spread-options strong{display:block;font-weight:500;font-size:13px}.spread-options small{display:block;font-size:10px}.tarot-sanctum button{font:inherit;cursor:pointer;box-shadow:none;transition:background .15s,color .15s}.gold-button{display:flex;align-items:center;justify-content:space-between;gap:30px;min-width:180px;padding:10px 16px;border:1px solid #d1b984;border-radius:5px;background:#d1b984;color:#182026;font-weight:500!important}.gold-button:hover{background:#e2ceaa}.tarot-sanctum button:disabled{cursor:default;opacity:.45}.quiet-button{background:transparent;border:1px solid #465359;color:#c0c6bf;border-radius:5px;padding:7px 11px;font-size:12px!important}.tarot-sanctum :focus-visible{outline:2px solid #e2c998;outline-offset:4px}.table-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:20px 22px 12px}.table-heading h2{margin:0}.table-controls{padding:15px 22px 22px;border-top:1px solid #344047}.table-controls>p{font-size:12px;color:#cbbfa3;margin:0 0 12px}.card-numbers{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:4px}.card-numbers button{border:1px solid #455259;background:#1c2930;color:#b8c0bc;border-radius:4px;padding:7px 0;position:relative;font-size:11px}.card-numbers button.picked{border-color:#c8b07c;color:#e0c997;background:#34413a}.card-numbers span{position:absolute;top:-8px;right:3px;font-size:20px}.selected-slots{display:flex;flex-wrap:wrap;gap:7px;margin:16px 0 20px}.selected-slots>span{flex:1 0 80px;border-left:1px solid #48534e;padding:0 9px}.selected-slots small{display:block;font-size:10px;color:#9ca6a4}.selected-slots strong{font-size:12px;font-weight:400;color:#87938f}.selected-slots .filled strong{color:#d1b984}.guide-panel{display:flex;flex-direction:column;background:#182127;border:1px solid #344047;border-radius:10px;padding:18px;align-self:start;min-width:0}.guide-heading{display:flex;align-items:center;gap:10px;padding-bottom:17px;border-bottom:1px solid #344047}.guide-avatar{display:grid;place-items:center;width:35px;height:35px;border:1px solid #8b7e60;border-radius:50%;font-size:23px;color:#d1b984}.guide-heading strong{display:block;font-weight:500;font-size:14px}.guide-heading small{display:block;font-size:10px;color:#9fa9a6}.guide-messages{display:flex;flex-direction:column;gap:12px;padding:20px 0}.guide-bubble{background:#263238;border:1px solid #3a484c;border-radius:2px 10px 10px 10px;padding:12px}.guide-bubble.you{background:#303931;border-color:#53604c;border-radius:10px 2px 10px 10px}.guide-bubble small{font-size:10px;color:#c6b68e}.guide-bubble p{font-size:13px;line-height:1.85;margin:4px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}.guide-footer{border-top:1px solid #344047;padding-top:16px}.mini-star{font-size:19px;color:#b8a373}.guide-footer p{font-size:12px;color:#b0b7ae;margin:6px 0 10px}.guide-footer small{color:#8e9c9d;font-size:10px;display:block}.reading-section{padding:22px;border-top:1px solid #344047}.reading-tabs{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:20px}.reading-tabs button{border:1px solid #455359;border-radius:4px;background:#1a262d;color:#aeb9b3;font-size:11px;padding:6px 9px}.reading-tabs button.active{color:#e6d3ad;border-color:#bca573;background:#343b31}.reading-title{display:flex;gap:17px;align-items:center;margin-bottom:22px}.reading-title>span{font:38px/1 Georgia;color:#b6a178}.reading-title small{color:#a8b4ae;font-size:11px}.reading-title h2{margin:2px 0}.reading-detail h3{color:#dbc79e}.reading-detail p{font-size:1